//! Parity tests for the logical table-name registry against fixtures
//! generated by running the REAL cine_rec_engine/tables.py
//! (fixtures/tables_cases.json — see fixtures/gen_tables_cases.py).
//!
//! Every accept/reject decision, resolved SQL string and ERROR TEXT
//! must match Python exactly. io_edge cases (reading a missing map
//! file) are skipped here on purpose: file IO is the runtime edge
//! wave D owns; this crate takes the already-parsed map.

use cine_rec_ingest::tables::TableMap;
use serde_json::Value;

#[test]
fn table_map_matches_python_decisions_and_messages() {
    let doc: Value = serde_json::from_str(include_str!("fixtures/tables_cases.json")).unwrap();
    let cases = doc["cases"].as_array().unwrap();
    assert!(cases.len() >= 25, "only {} cases", cases.len());

    let mut checked = 0;
    for case in cases {
        let name = case["name"].as_str().unwrap();
        if case["io_edge"].as_bool().unwrap_or(false) {
            continue; // Python-only: the file-reading edge is wave D's
        }
        checked += 1;

        let map = match case["install"].as_str().unwrap() {
            "set" | "identity" => {
                let pairs: Vec<(&str, &str)> = case["pairs"]
                    .as_array()
                    .map(|a| {
                        a.iter()
                            .map(|p| (p[0].as_str().unwrap(), p[1].as_str().unwrap_or("")))
                            .collect()
                    })
                    .unwrap_or_default();
                TableMap::from_pairs(pairs)
            }
            "load" => {
                let env: Vec<(String, String)> = case["env"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| {
                        (
                            p[0].as_str().unwrap().to_string(),
                            p[1].as_str().unwrap().to_string(),
                        )
                    })
                    .collect();
                let file = case.get("file").filter(|f| !f.is_null());
                let path = case
                    .get("file_path")
                    .and_then(|p| p.as_str())
                    .or(Some("map.json"));
                TableMap::from_file_and_env(path, file, &env)
            }
            other => panic!("unknown install kind {other}"),
        };

        let expect = &case["expect"];
        match (map, expect.get("error")) {
            (Err(e), Some(want)) => {
                assert_eq!(
                    e.to_string(),
                    want.as_str().unwrap(),
                    "{name}: error message drifted"
                );
            }
            (Err(e), None) => panic!("{name}: errored ({e}), Python succeeded"),
            (Ok(_), Some(want)) => {
                panic!("{name}: succeeded, Python errored: {}", want)
            }
            (Ok(m), None) => {
                // active map — only the non-default mappings.
                let want = expect["active"].as_object().unwrap();
                let got: std::collections::BTreeMap<&str, &str> = m
                    .active_map()
                    .iter()
                    .map(|(k, v)| (*k, v.as_str()))
                    .collect();
                assert_eq!(
                    got.len(),
                    want.len(),
                    "{name}: active map size differs: {got:?} vs {want:?}"
                );
                for (k, v) in want {
                    assert_eq!(
                        got.get(k.as_str()).copied().unwrap_or("<absent>"),
                        v.as_str().unwrap(),
                        "{name}: active[{k}]"
                    );
                }

                // name() probes — values or exact error texts.
                for probe in expect["names"].as_array().unwrap() {
                    let logical = probe[0].as_str().unwrap();
                    let want = &probe[1];
                    match m.name(logical) {
                        Ok(got) => {
                            assert_eq!(got, want.as_str().unwrap(), "{name}: name({logical})")
                        }
                        Err(e) => assert_eq!(
                            e.to_string(),
                            want["error"].as_str().unwrap(),
                            "{name}: name({logical}) message"
                        ),
                    }
                }

                // resolve() probes — rendered SQL or exact error texts.
                for probe in expect["resolves"].as_array().unwrap() {
                    let template = probe[0].as_str().unwrap();
                    let want = &probe[1];
                    match m.resolve(template) {
                        Ok(got) => {
                            assert_eq!(got, want.as_str().unwrap(), "{name}: resolve({template:?})")
                        }
                        Err(e) => assert_eq!(
                            e.to_string(),
                            want["error"].as_str().unwrap(),
                            "{name}: resolve({template:?}) message"
                        ),
                    }
                }
            }
        }
    }
    assert!(checked >= 25, "only {checked} non-io_edge cases ran");
}
